IF DATALENGTH(@Pdf) <> 2787616
    THROW 50003, 'El tamaño del PDF generado no coincide con el archivo original.', 1;

DECLARE @FilasAfectadas int;

UPDATE dbo.MANUAL_USUARIO
SET Pdf = @Pdf,
    FechaPublicacion = SYSUTCDATETIME(),
    UsuarioPublicacion = COALESCE(ORIGINAL_LOGIN(), SUSER_SNAME(), N'Sistemas')
WHERE ManualUsuario_ID = 1;

SET @FilasAfectadas = @@ROWCOUNT;

IF @FilasAfectadas = 0
BEGIN
    INSERT INTO dbo.MANUAL_USUARIO (
        ManualUsuario_ID,
        Pdf,
        FechaPublicacion,
        UsuarioPublicacion
    )
    VALUES (
        1,
        @Pdf,
        SYSUTCDATETIME(),
        COALESCE(ORIGINAL_LOGIN(), SUSER_SNAME(), N'Sistemas')
    );

    SET @FilasAfectadas = @@ROWCOUNT;
END;

IF @FilasAfectadas <> 1
    THROW 50004, 'No se actualizó o insertó exactamente un manual.', 1;

SELECT @FilasAfectadas AS FilasAfectadas;

SELECT ManualUsuario_ID,
       DATALENGTH(Pdf) AS BytesPdf,
       CONVERT(varchar(64), HASHBYTES('SHA2_256', Pdf), 2) AS Sha256Pdf,
       FechaPublicacion,
       UsuarioPublicacion
FROM dbo.MANUAL_USUARIO
WHERE ManualUsuario_ID = 1;

